package com.gemini.guard

import android.content.Context
import java.util.Locale

/**
 * Ngon ngu giao dien. Nguon chuoi la tieng Viet; khi chon English thi tra ve ban dich trong EN
 * (thieu ban dich thi giu tieng Viet). "auto" = theo ngon ngu he thong (vi -> Viet, con lai -> English).
 */
object L {
    @Volatile var vi = true

    fun load(c: Context) {
        val m = Restorer.prefs(c).getString("lang", "auto") ?: "auto"
        vi = when (m) {
            "vi" -> true
            "en" -> false
            else -> Locale.getDefault().language == "vi"
        }
    }

    fun tr(s: String): String = if (vi) s else (EN[s] ?: s)

    fun fmt(s: String, vararg a: Any?): String = String.format(tr(s), *a)

